function describe(node, depth) {
  if (!node) return null;
  const out = {
    id: node.id, name: node.name, type: node.type,
    x: node.x, y: node.y, width: node.width, height: node.height,
  };
  if ('fills' in node) out.fills = node.fills;
  if ('strokes' in node) out.strokes = node.strokes;
  if ('strokeWeight' in node) out.strokeWeight = node.strokeWeight;
  if ('cornerRadius' in node) out.cornerRadius = node.cornerRadius;
  if ('layoutMode' in node) { out.layoutMode = node.layoutMode; out.paddingLeft = node.paddingLeft; out.paddingRight = node.paddingRight; out.paddingTop = node.paddingTop; out.paddingBottom = node.paddingBottom; out.itemSpacing = node.itemSpacing; out.primaryAxisSizingMode = node.primaryAxisSizingMode; out.counterAxisSizingMode = node.counterAxisSizingMode; }
  if (node.type === 'TEXT') {
    out.characters = node.characters;
    out.fontName = node.fontName;
    out.fontSize = node.fontSize;
    out.lineHeight = node.lineHeight;
    out.letterSpacing = node.letterSpacing;
    out.textCase = node.textCase;
  }
  if ('children' in node && depth > 0) {
    out.children = node.children.map(c => describe(c, depth - 1));
  }
  return out;
}
const button = figma.getNodeById('1:29');
const textField = figma.getNodeById('1:32');
const result = {
  button: describe(button, 4),
  textField: describe(textField, 4),
};
return JSON.stringify(result, null, 1);

