  return JSON.stringify({ok:true, h: priv.height});
}
return run();

async function run() {
  const page = await figma.getNodeByIdAsync('3:2');
  await figma.setCurrentPageAsync(page);

  const pageNames = ['01_Home','02_Blog','03_Blog_Post','04_About_Us','05_Category_Business','06_Author','07_Contact','08_Privacy_Policy'];
  const frames = {};
  for (const n of pageNames) {
    frames[n] = figma.currentPage.findOne(x => x.name===n && x.type==='FRAME');
  }

  async function wire(node, destName, name) {
    if (!node) { return {missing:true, name}; }
    const dest = frames[destName];
    if (!dest) return {missingDest:true, destName};
    await node.setReactionsAsync([{
      trigger: {type:'ON_CLICK'},
      actions: [{type:'NODE', destinationId: dest.id, navigation:'NAVIGATE', transition:null, preserveScrollPosition:false}]
    }]);
    return {ok:true};
  }

  const report = [];

  for (const pname of pageNames) {
    const frame = frames[pname];
    if (!frame) { report.push({pname, error:'frame not found'}); continue; }
    const headerInst = frame.findOne(n=>n.name==='Comp/Header' || (n.type==='INSTANCE' && n.name==='Comp/Header'));
    // header may be named 'Comp/Header' as instance default name
    const header = frame.children.find(c => c.type==='INSTANCE' && c.mainComponent && c.mainComponent.name==='Comp/Header');
    if (header) {
      const nav = header.findOne(n=>n.name==='Nav');
      if (nav) {
        for (const child of nav.children) {
          let dest = null;
          if (child.name==='Nav/Home') dest='01_Home';
          else if (child.name==='Nav/Blog') dest='02_Blog';
          else if (child.name==='Nav/About Us') dest='04_About_Us';
          else if (child.name==='Nav/Contact us') dest='07_Contact';
          if (dest) report.push(await wire(child, dest, pname+':'+child.name));
        }
      }
    }
    const footer = frame.children.find(c => c.type==='INSTANCE' && c.mainComponent && c.mainComponent.name==='Comp/Footer');
    if (footer) {
      const link = footer.findOne(n=>n.name==='Link/Privacy Policy');
      if (link) report.push(await wire(link, '08_Privacy_Policy', pname+':footerPrivacy'));
      const homeLink = footer.findOne(n=>n.name==='Link/Home');
      if (homeLink) report.push(await wire(homeLink, '01_Home', pname+':footerHome'));
      const blogLink = footer.findOne(n=>n.name==='Link/Blog');
      if (blogLink) report.push(await wire(blogLink, '02_Blog', pname+':footerBlog'));
      const aboutLink = footer.findOne(n=>n.name==='Link/About us');
      if (aboutLink) report.push(await wire(aboutLink, '04_About_Us', pname+':footerAbout'));
      const contactLink = footer.findOne(n=>n.name==='Link/Contact us');
      if (contactLink) report.push(await wire(contactLink, '07_Contact', pname+':footerContact'));
    }
  }

  return JSON.stringify(report);
}
return run();

async function run() {
  const page = await figma.getNodeByIdAsync('3:2');
