    if (!node) return {missing:true, label};
    if (destName === pname) return {skippedSelf:true, label};
    const dest = frames[destName];
    if (!dest) return {missingDest:true, destName};
    try {
      await node.setReactionsAsync([{
        trigger: {type:'ON_CLICK'},
        actions: [{type:'NODE', destinationId: dest.id, navigation:'NAVIGATE', transition:null, preserveScrollPosition:false}]
      }]);
      return {ok:true, label};
    } catch(e) {
      return {error: e.message, label};
    }
  }

  const report = [];

  for (const pname of pageNames) {
    const frame = frames[pname];
    if (!frame) { report.push({pname, error:'frame not found'}); continue; }
    const header = frame.children.find(c => c.type==='INSTANCE' && c.mainComponent && c.mainComponent.name==='Comp/Header');
    if (header) {
      const nav = header.findOne(n=>n.name==='Nav');
      if (nav) {
        for (const child of nav.children) {
          let dest = null;
          if (child.name==='Nav/Home') dest='01_Home';
          else if (child.name==='Nav/Blog') dest='02_Blog';
          else if (child.name==='Nav/About Us') dest='04_About_Us';
          else if (child.name==='Nav/Contact us') dest='07_Contact';
          if (dest) report.push(await wire(child, dest, pname, pname+':'+child.name));
        }
      }
    }
    const footer = frame.children.find(c => c.type==='INSTANCE' && c.mainComponent && c.mainComponent.name==='Comp/Footer');
    if (footer) {
      const links = [['Link/Privacy Policy','08_Privacy_Policy'],['Link/Home','01_Home'],['Link/Blog','02_Blog'],['Link/About us','04_About_Us'],['Link/Contact us','07_Contact']];
      for (const [lname, dest] of links) {
        const link = footer.findOne(n=>n.name===lname);
        if (link) report.push(await wire(link, dest, pname, pname+':footer:'+lname));
      }
    }
  }

  return JSON.stringify(report);
}
return run();

async function run() {
  const page = await figma.getNodeByIdAsync('3:2');
  await figma.setCurrentPageAsync(page);
  const pageNames = ['01_Home','02_Blog','03_Blog_Post','04_About_Us','05_Category_Business','06_Author','07_Contact','08_Privacy_Policy'];
  const frames = {};
  for (const n of pageNames) frames[n] = figma.currentPage.findOne(x => x.name===n && x.type==='FRAME');

  async function wire(node, destName, label) {
    if (!node) return {missing:true, label};
    const dest = frames[destName];
    if (!dest) return {missingDest:true, label};
    try {
      await node.setReactionsAsync([{trigger:{type:'ON_CLICK'}, actions:[{type:'NODE', destinationId: dest.id, navigation:'NAVIGATE', transition:null, preserveScrollPosition:false}]}]);
      return {ok:true, label};
    } catch(e) { return {error:e.message, label}; }
  }

  const report = [];

  // ----- 01_Home -----
  const home = frames['01_Home'];
  const hero = home.findOne(n=>n.name==='Hero');
  const heroReadMore = hero.findOne(n=>n.type==='TEXT' && n.characters==='Read More >');
  report.push(await wire(heroReadMore, '03_Blog_Post', '01_Home:heroReadMore'));
  const apHead = home.findOne(n=>n.name==='AllPosts').findOne(n=>n.name==='Head');
  const viewAll = apHead.findOne(n=>n.type==='TEXT' && n.characters==='View All');
  report.push(await wire(viewAll, '02_Blog', '01_Home:viewAll'));
  const homeCatRow = home.findOne(n=>n.name==='Categories').findOne(n=>n.name==='Row');
  const homeBizCard = homeCatRow.children.find(c => c.findOne(n=>n.name==='Name' && n.characters==='Business'));
  report.push(await wire(homeBizCard, '05_Category_Business', '01_Home:bizCard'));

  // ----- 02_Blog -----
  const blog = frames['02_Blog'];
  const feat = blog.findOne(n=>n.name==='Featured');
  const featReadMore = feat.findOne(n=>n.type==='TEXT' && n.characters==='Read More >');
  report.push(await wire(featReadMore, '03_Blog_Post', '02_Blog:featReadMore'));
  const blogCatRow = blog.findOne(n=>n.name==='Categories').findOne(n=>n.name==='Row');
  const blogBizCard = blogCatRow.children.find(c => c.findOne(n=>n.name==='Name' && n.characters==='Business'));
  report.push(await wire(blogBizCard, '05_Category_Business', '02_Blog:bizCard'));
  // post item read more -> also link whole post items to 03_Blog_Post (first item)
  const list = blog.findOne(n=>n.name==='AllPosts').findOne(n=>n.name==='List');
  for (const item of list.children) {
    report.push(await wire(item, '03_Blog_Post', '02_Blog:postItem'));
  }

  // ----- 03_Blog_Post -----
  const post = frames['03_Blog_Post'];
  const authorNameNode = post.findOne(n=>n.name==='AuthorName');
  report.push(await wire(authorNameNode, '06_Author', '03_Blog_Post:authorName'));

  // ----- 05_Category_Business -----
  const cat5 = frames['05_Category_Business'];
  const crumb = cat5.findOne(n=>n.name==='Breadcrumb');
